<script setup lang="ts">
import { computed, ref } from 'vue'
import * as api from '../domain/api'
import { priceFormat, type Category } from '../domain/catalog'
const props=defineProps<{categoryId:number;categories:Category[]}>();const emit=defineEmits<{close:[];changed:[]}>()
const operation=ref<api.BulkOperation>({mode:'price',percent:5,targetCategory:props.categoryId,attributeName:'',attributeValue:''});const jobs=ref<api.ImportJob[]>([]);const total=ref(0);const preparing=ref(false);const applying=ref(false);const stopped=ref(false);const error=ref('');const prepared=ref(false)
const done=computed(()=>jobs.value.reduce((n,j)=>n+j.cursor,0));const errors=computed(()=>jobs.value.flatMap((j,i)=>j.errors.map(e=>`Часть ${i+1}, строка ${e.row}: ${e.message}`)));const sample=computed(()=>jobs.value.flatMap(j=>j.preview).slice(0,20));const failed=computed(()=>jobs.value.find(j=>j.failed)?.failed)
async function prepare(){preparing.value=true;prepared.value=false;jobs.value=[];error.value='';stopped.value=false;try{const scope=await api.getBulkScope(props.categoryId);total.value=scope.total;if(!scope.total)throw new Error('В разделе нет товаров.');for(let i=0;i<scope.ids.length;i+=200){if(stopped.value)break;jobs.value.push(await api.previewBulkCategory(props.categoryId,scope.ids.slice(i,i+200),operation.value))}prepared.value=!stopped.value;if(prepared.value&&!errors.value.length)sessionStorage.setItem('ukm-office-bulk',JSON.stringify({categoryId:props.categoryId,operation:operation.value,total:total.value,jobs:jobs.value.map(j=>j.job)}))}catch(e){error.value=e instanceof Error?e.message:'Не удалось подготовить операцию'}finally{preparing.value=false}}
async function apply(){if(!prepared.value||errors.value.length||applying.value)return;if(!confirm(`Применить операцию к ${total.value} товарам раздела на тестовом сайте? Выполненные правки сохраняются в истории.`))return;applying.value=true;stopped.value=false;error.value='';try{for(let i=0;i<jobs.value.length;i++){while(!jobs.value[i]!.complete&&!jobs.value[i]!.failed&&!stopped.value)jobs.value[i]=await api.applyImport(jobs.value[i]!.job,jobs.value[i]!.cursor);if(stopped.value||jobs.value[i]!.failed)break}if(done.value===total.value)sessionStorage.removeItem('ukm-office-bulk');emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Ошибка сохранения. Обновите прогресс перед повтором.'}finally{applying.value=false}}
async function restore(){const raw=sessionStorage.getItem('ukm-office-bulk');if(!raw)return;preparing.value=true;error.value='';try{const saved=JSON.parse(raw);if(saved.categoryId!==props.categoryId)throw new Error('Сохранённая операция относится к другому разделу. Откройте соответствующий раздел.');operation.value=saved.operation;total.value=saved.total;jobs.value=[];for(const id of saved.jobs)jobs.value.push(await api.getImport(id));prepared.value=true}catch(e){error.value=e instanceof Error?e.message:'Операция истекла; подготовьте её заново.'}finally{preparing.value=false}}
function close(){if(preparing.value||applying.value)return;if(done.value>0&&done.value<total.value&&!confirm('Закрыть окно? Уже выполненные изменения останутся в истории. Операцию можно продолжить через «Обновить прогресс».'))return;emit('close')}
</script>
<template><div class="modal-backdrop"><section class="modal bulk-category" role="dialog" aria-modal="true" aria-labelledby="bulk-category-title"><div class="modal-heading"><h2 id="bulk-category-title">Массовая правка всего раздела</h2><button class="icon-button" :disabled="preparing||applying" aria-label="Закрыть массовую правку" @click="close">×</button></div><p class="muted">{{ categories.find(c=>c.id===categoryId)?.name }} · включая подразделы</p><fieldset :disabled="preparing||applying||prepared"><label>Операция<select v-model="operation.mode"><option value="price">Изменить основные цены на процент</option><option value="category">Перенести в другую категорию</option><option value="attribute">Изменить характеристику</option></select></label><label v-if="operation.mode==='price'">Процент изменения<input v-model.number="operation.percent" type="number" min="-99.99" max="100000" step="0.01" /></label><label v-else-if="operation.mode==='category'">Новая категория<select v-model="operation.targetCategory"><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><template v-else><label>Характеристика<input v-model="operation.attributeName" /></label><label>Значение<input v-model="operation.attributeValue" /></label></template></fieldset><p class="info-box">Сначала фиксируем список товаров и проверяем все части. После подтверждения обрабатываем по пять товаров. Новые товары, добавленные в раздел позже, не включаются. При изменении открытой версии товара операция остановится.</p><p v-if="error" class="error-notice" role="alert">{{ error }}</p><div v-if="errors.length" class="error-notice" role="alert"><p v-for="e in errors.slice(0,20)" :key="e">{{ e }}</p><p>Ошибок: {{ errors.length }}. Ничего не применено. Уточните данные и подготовьте операцию заново.</p></div><p v-if="failed" class="error-notice">Остановлено: {{ failed.message }}. Выполненные {{ done }} правок доступны в истории.</p><p v-if="total" role="status">Товаров: {{ total }} · Подготовлено: {{ jobs.reduce((n,j)=>n+j.total,0) }} · Сохранено: {{ done }}</p><div v-if="sample.length" class="bulk-preview"><div v-for="p in sample" :key="p.id"><span>{{ p.name }}</span><strong v-if="operation.mode==='price'">{{ p.price===null?'Без цены':priceFormat.format(p.price)+' ₽' }}</strong></div><p class="muted">Показаны первые {{ sample.length }} позиций; операция включает {{ total }}.</p></div><div class="modal-actions"><button v-if="preparing||applying" class="button" @click="stopped=true">Остановить после текущей части</button><template v-else><button class="button" @click="restore">Обновить прогресс</button><button v-if="!prepared" class="button primary" @click="prepare">Подготовить предпросмотр</button><button v-else-if="done<total&&!failed&&!errors.length" class="button primary" @click="apply">{{ done?'Продолжить':'Подтвердить и применить' }}</button><button v-if="prepared&&done===0" class="button" @click="prepared=false;jobs=[]">Изменить условия</button><button class="button" @click="close">Закрыть</button></template></div></section></div></template>
